      rect(this.x, this.y + i * stripeHeight, this.w, stripeHeight);
    }

    for (let i = numcolours - 2; i >= 0; i--) {
      fill(colours[i]);
      noStroke();
      rect(this.x, this.y + (numcolours + (numcolours - 2 - i)) * stripeHeight, this.w, stripeHeight);
    }
  }
