const cols = 3; // Number of columns
const spacing = 20; // Spacing between flags
const flagWidth = 150; // Standard flag width
const flagHeight = flagWidth * (2 / 3); // Standard flag height with 3:2 ratio

let flagObjects = [];
let flagNoise;
let pg;

function noiseTexture() {
  pg = createGraphics(width, height);
  pg.noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01) * width * 0.002;
    pg.fill('#eac96e');
    pg.ellipse(x, y, n, n);
  }
}

function setup() {
  createCanvas(800, 800);

  let shuffledPrideFlags = shuffle([...prideFlags]);

  let totalWidth = cols * (flagWidth + spacing) - spacing; // Columns times the width of each flag plus spacing, minus one spacing
  let rows = ceil(prideFlags.length / cols);
  let totalHeight = rows * (flagHeight + spacing) - spacing; // Rows times the height of each flag plus spacing, minus one spacing
  let startX = (width - totalWidth) / 2;
  let startY = (height - totalHeight) / 2;

  for (let i = 0; i < prideFlags.length; i++) {
    let col = i % cols; // Use the number of columns instead of rows
    let row = floor(i / cols); // Divide by the number of columns instead of rows

    let x = startX + col * (flagWidth + spacing);
    let y = startY + row * (flagHeight + spacing);

    let flag = new Flag(shuffledPrideFlags[i].name, shuffledPrideFlags[i].colours, shuffledPrideFlags[i].instructions, shuffledPrideFlags[i].ratios, shuffledPrideFlags[i].chevrons, x, y, flagWidth, flagHeight);
    flagObjects.push(flag);
  }


  // make an img buffer as big as a flag
  flagNoise = createGraphics(flagWidth, flagHeight);
  noiseGradient(255, 0, 0, flagWidth, flagHeight, "left", 0.2)


  strokeJoin(ROUND);
  noiseTexture();
  blendMode(BLEND);
}



function draw() {
  // noLoop();
  background('#f9eac0');
  image(pg, 0, 0);

  for (let i = 0; i < flagObjects.length; i++) {
    let flag = flagObjects[i];
		flag.handleHover();
    flag.draw();
    blendMode(SOFT_LIGHT);
    // Draw the flag onto the buffer
    image(flagNoise, flag.x, flag.y);
    blendMode(BLEND); // Reset blend mode to normal 
  }


  for (let flag of flagObjects) {
    if (flag.hovered) {
      flag.showName();
      break;
    }
  }
}

function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]]; // Swap the elements
  }
  return array;
}

function noiseGradient(_c, _x, _y, _w, _h, direction = "left", _density = 0.1) {
  const density = min(1, _density);
  const c = _c;
  const num = _w * _h * density;
  const ns = 0.01;
  flagNoise.noStroke();
  flagNoise.fill(240, 100);
  for (let i = 0; i < num; i++) {
    let x, y;
    switch (direction) {
      case "right":
        x = _w - abs(randomGaussian()) / 5 * _w;
        y = random(_h);
        break;
      case "up": // formerly "vertical"
        x = random(_w);
        y = abs(randomGaussian()) / 5 * _h;
        break;
      case "down":
        x = random(_w);
        y = _h - abs(randomGaussian()) / 5 * _h;
        break;
      default: // "left" formerly "horizontal"
        x = abs(randomGaussian()) / 8 * _w;
        y = random(_h);
        break;
    }
    const dia = noise(x * ns, y * ns) * 0.5 + 1;
    flagNoise.ellipse(x + _x, y + _y, dia, dia);
  }
}

